using PactNet.Infrastructure.Outputters;
using PactNet.Verifier;
using Xunit;
using Xunit.Abstractions;

namespace Catalog.Tests.ContractTest.Provider
{
    /// <summary>
    /// Provider side of the contract. Pact replays every interaction defined by the consumer
    /// (the pact file generated by <c>CatalogApiConsumerTests</c>) against the running Catalog
    /// API and fails if the provider stops honouring the agreed contract.
    /// </summary>
    public class CatalogApiProviderTests : IClassFixture<CatalogApiProviderFixture>
    {
        private readonly CatalogApiProviderFixture _fixture;
        private readonly ITestOutputHelper _output;

        public CatalogApiProviderTests(CatalogApiProviderFixture fixture, ITestOutputHelper output)
        {
            _fixture = fixture;
            _output = output;
        }

        [Fact]
        public void CatalogApi_HonoursConsumerContract()
        {
            //Arrange
            Assert.True(File.Exists(PactPaths.PactFile),
                $"Pact file not found at '{PactPaths.PactFile}'. Generate it first with: " +
                "dotnet test Test/Test.csproj --filter \"FullyQualifiedName~Catalog.Tests.ContractTest.Consumer\"");

            var config = new PactVerifierConfig
            {
                Outputters = new IOutput[] { new XUnitOutput(_output) }
            };

            //Act / Assert
            using var verifier = new PactVerifier(PactPaths.Provider, config);

            verifier
                .WithHttpEndpoint(_fixture.ServerUri)
                .WithFileSource(new FileInfo(PactPaths.PactFile))
                .WithProviderStateUrl(new Uri(_fixture.ServerUri, "provider-states"))
                .Verify();
        }
    }
}